let myShader,
		mouse = [0, 0, 0];
let pimg;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	myShader = createShader(vert, frag);
	shader(myShader);
  noStroke();
	pimg = loadImage('https://openprocessing.org/sketch/495460/files/metal.jpg');

  let c = document.getElementById('defaultCanvas0');
  console.log(c);
  c.addEventListener('contextmenu', e => { e.preventDefault(); });
}

function mousePressed(event) {
  mouse[event.which - 1] = 1;
}

function mouseReleased(event) {
  mouse[event.which - 1] = 0;
}

function draw() {
  rectMode(CENTER);
	background(0);
	shader(myShader);
	myShader.setUniform('time', millis());
	myShader.setUniform('res', [width, height]);
	myShader.setUniform('aspect', width/height);
	myShader.setUniform('mouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), height - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), mouse[0], mouse[2]]);
	myShader.setUniform('texture0', pimg);

  rect(0,0,width, height);
}

